const useStyles = makeStyles(theme => ({
    warm: {backgroundColor: Color.orange['500']},
    textarea: {width: "100%", minHeight: "200px"},
}));

const placeholder = {
    query: JSON.stringify({
        "query": {
            "match" : {
                "message" : {
                    "query" : "$keyword"
